import Link from 'next/link';
import {requireVendorMember} from '@/lib/vendors';
import {prisma} from '@/lib/prisma';
export const dynamic='force-dynamic';
export default async function VendorProducts({searchParams}:{searchParams:Promise<{vendorId?:string}>}){const p=await searchParams;const {vendor}=await requireVendorMember(p.vendorId);const rows=await prisma.template.findMany({where:{vendorId:vendor.id},orderBy:{updatedAt:'desc'},take:50});return <main className="admin-content"><div className="flex items-end justify-between"><div><p className="eyebrow">VENDOR PRODUCTS</p><h1 className="admin-title">{vendor.storeName}</h1></div><Link href={`/vendor/products/new?vendorId=${vendor.id}`} className="btn-primary">New product</Link></div><div className="admin-panel mt-8 overflow-x-auto"><table className="admin-table"><thead><tr><th>Product</th><th>Status</th><th>Moderation</th><th>Price</th></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td><Link className="text-violet-300" href={`/vendor/products/${row.id}/edit?vendorId=${vendor.id}`}>{row.name}</Link></td><td>{row.status}</td><td>{row.vendorStatus}</td><td>{row.priceMmk.toLocaleString()} MMK</td></tr>)}</tbody></table>{!rows.length&&<p className="admin-empty">No vendor products yet.</p>}</div></main>}
